<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/admin_crud_helpers.php';
require_role(['admin','siswa']);
$isAdmin = (current_user()['role'] ?? '') === 'admin';
$errors = [];
$edit=null;if($isAdmin&&isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM pengumuman WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(PDO::FETCH_ASSOC);}
if($isAdmin&&$_SERVER['REQUEST_METHOD']==='POST'){sg_verify_csrf();$action=$_POST['action']??'';if($action==='delete'){$q=$pdo->prepare('DELETE FROM pengumuman WHERE id=?');$q->execute([(int)$_POST['id']]);sg_flash_redirect('Pengumuman berhasil dihapus.',BASE_URL.'/dashboard/pengumuman.php');}$judul=trim($_POST['judul']??'');$isi=trim($_POST['isi']??'');$tanggal=$_POST['tanggal_publikasi']??'';$status=$_POST['status']??'aktif';if($judul===''||$isi===''||!$tanggal||!in_array($status,['aktif','arsip'],true))$errors[]='Lengkapi judul, isi, tanggal, dan status.';if(!$errors){if($action==='update'){$q=$pdo->prepare('UPDATE pengumuman SET judul=?,isi=?,tanggal_publikasi=?,status=? WHERE id=?');$q->execute([$judul,$isi,$tanggal,$status,(int)$_POST['id']]);}else{$q=$pdo->prepare('INSERT INTO pengumuman(judul,isi,tanggal_publikasi,status) VALUES(?,?,?,?)');$q->execute([$judul,$isi,$tanggal,$status]);}sg_flash_redirect('Pengumuman berhasil disimpan.',BASE_URL.'/dashboard/pengumuman.php');}$edit=['id'=>$_POST['id']??0,'judul'=>$judul,'isi'=>$isi,'tanggal_publikasi'=>$tanggal,'status'=>$status];}
$sql="SELECT * FROM pengumuman";$params=[];if(!$isAdmin){$sql.=" WHERE status='aktif'";}$sql.=" ORDER BY tanggal_publikasi DESC,id DESC";$rows=$pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Pengumuman — STEINS GATE';include __DIR__.'/../includes/dashboard_page_start.php';?>
<div class="page-heading"><div><div class="section-kicker">CLASS ANNOUNCEMENTS</div><h1>Pengumuman <em>Kelas.</em></h1><p>Informasi penting untuk siswa IPA 2.</p></div><?php if($isAdmin):?><a href="#form-pengumuman" class="btn btn-brown"><i class="bi bi-plus-lg me-1"></i>Buat Pengumuman</a><?php endif;?></div><?php sg_show_flash();foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?>
<?php if($isAdmin):?><div class="sg-panel mb-4" id="form-pengumuman"><h3><?=$edit?'Ubah Pengumuman':'Buat Pengumuman'?></h3><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=e($edit['id'])?>"><?php endif;?><div class="col-md-6"><label class="form-label">Judul</label><input name="judul" class="form-control custom-input" value="<?=e($edit['judul']??'')?>" required></div><div class="col-md-3"><label class="form-label">Tanggal Publikasi</label><input type="date" name="tanggal_publikasi" class="form-control custom-input" value="<?=e($edit['tanggal_publikasi']??date('Y-m-d'))?>" required></div><div class="col-md-3"><label class="form-label">Status</label><select name="status" class="form-select custom-input"><option value="aktif" <?=($edit['status']??'aktif')==='aktif'?'selected':''?>>Aktif</option><option value="arsip" <?=($edit['status']??'')==='arsip'?'selected':''?>>Arsip</option></select></div><div class="col-12"><label class="form-label">Isi Pengumuman</label><textarea name="isi" rows="4" class="form-control custom-input" required><?=e($edit['isi']??'')?></textarea></div><div class="col-12"><button class="btn btn-brown">Simpan</button> <?php if($edit):?><a class="btn btn-outline-secondary" href="<?=BASE_URL?>/dashboard/pengumuman.php">Batal</a><?php endif;?></div></form></div><?php endif;?>
<div class="d-grid gap-3"><?php foreach($rows as $r):?><article class="sg-panel"><div class="d-flex justify-content-between flex-wrap gap-2 mb-2"><span class="sg-badge"><?=e(ucfirst($r['status']))?></span><span class="sg-meta"><?=date('d M Y',strtotime($r['tanggal_publikasi']))?></span></div><h3><?=e($r['judul'])?></h3><p class="mb-0"><?=nl2br(e($r['isi']))?></p><?php if($isAdmin):?><div class="mt-3 d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus pengumuman ini?')"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></div><?php endif;?></article><?php endforeach;?></div><?php if(!$rows):?><div class="sg-panel text-center">Belum ada pengumuman.</div><?php endif;?><?php include __DIR__.'/../includes/dashboard_page_end.php';?>